const server = app.listen(3000, "127.0.0.1", async () => {
  const baseUrl = "http://127.0.0.1:3000";

  const listResponse = await fetch(`${baseUrl}/api/events`);
  const oneResponse = await fetch(`${baseUrl}/api/events/1`);
  const missingResponse = await fetch(`${baseUrl}/api/events/999`);
  const filterResponse = await fetch(`${baseUrl}/api/events?category=arts`);

